#include <iostream>
#include <string>
#include <vector>

void print(const std::string &title, const std::vector<long long> &v) {
    std::cout << title << ':';
    if (v.empty()) {
        std::cout << " нет";
    }
    for (long long x : v) {
        std::cout << ' ' << x;
    }
    std::cout << '\n';
}

int main() {
    std::vector<long long> even, odd;
    long long x;
    while (std::cin >> x) {
        (x % 2 == 0 ? even : odd).push_back(x);
    }
    print("чётные", even);
    print("нечётные", odd);
    return 0;
}

