#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::size_t k;
    if (!(std::cin >> k)) {
        return 0;
    }
    std::vector<std::string> files;
    std::string command;
    while (std::cin >> command) {
        if (command == "open") {
            std::string name;
            std::cin >> name;
            auto it = std::find(files.begin(), files.end(), name);
            if (it != files.end()) {
                files.erase(it);
            }
            files.insert(files.begin(), name);
            if (files.size() > k) {
                files.pop_back();
            }
        } else if (command == "list") {
            if (files.empty()) {
                std::cout << "пусто";
            }
            for (std::size_t i = 0; i < files.size(); i++) {
                std::cout << (i ? " " : "") << files[i];
            }
            std::cout << '\n';
        }
    }
    return 0;
}

