#include <iostream>
#include <vector>

int main() {
    std::vector<std::vector<int>> t(2, std::vector<int>(3, 1));
    t[1][2] = 5;
    int sum = 0;
    for (const auto &row : t) {
        for (int x : row) {
            sum += x;
        }
    }
    std::cout << t.size() << ' ' << t[0].size() << ' ' << sum << '\n';
